(function () {
  async function jsonRequest(url, body) {
    const response = await fetch(url, {
      method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body || {})
    });
    const result = await response.json().catch(function () { return {}; });
    if (!response.ok) throw new Error(result.error || ('HTTP ' + response.status));
    return result;
  }
  document.addEventListener('click', async function (event) {
    const login = event.target.closest('[data-passkey-login]');
    const register = event.target.closest('[data-passkey-register]');
    if (!login && !register) return;
    if (!window.SimpleWebAuthnBrowser || !window.SimpleWebAuthnBrowser.browserSupportsWebAuthn()) {
      return window.Toast ? Toast.error('当前浏览器不支持通行密钥') : alert('当前浏览器不支持通行密钥');
    }
    const button = login || register;
    button.disabled = true;
    try {
      if (login) {
        const options = await jsonRequest('/api/auth/passkey/options');
        const response = await window.SimpleWebAuthnBrowser.startAuthentication({ optionsJSON: options });
        await jsonRequest('/api/auth/passkey/verify', { response: response });
        location.href = '/admin/dashboard';
      } else {
        const name = prompt('给这个通行密钥起个名称', '此设备');
        if (name === null) return;
        const options = await jsonRequest('/admin/security/passkeys/register/options');
        const response = await window.SimpleWebAuthnBrowser.startRegistration({ optionsJSON: options });
        await jsonRequest('/admin/security/passkeys/register/verify', { response: response, name: name });
        if (window.Toast) Toast.success('通行密钥已添加');
        location.reload();
      }
    } catch (error) {
      if (window.Toast) Toast.error(error.message || '通行密钥操作失败');
      else alert(error.message || '通行密钥操作失败');
    } finally {
      button.disabled = false;
    }
  });
})();